package com.miniforce.controller;
import com.miniforce.dto.*; import com.miniforce.dto.UserDtos.*; import com.miniforce.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api") public class UserController {private final UserService users;private final CurrentUser current;public UserController(UserService u,CurrentUser c){users=u;current=c;}@GetMapping("/users/me") ProfileResponse me(){return users.profile(current.require());}@PutMapping("/users/me") UserResponse update(@Valid @RequestBody UpdateProfileRequest r){return users.update(current.require(),r);}@PutMapping("/users/me/avatar") UserResponse updateAvatar(@Valid @RequestBody UpdateAvatarRequest r){return users.updateAvatar(current.require(),r);}@GetMapping("/leaderboard") List<LeaderboardEntry> leaderboard(){return users.leaderboard();}}
